  (92, '1996', 'Callaway', 'C7', '', 'Hot Wheels', '', '', 'Retro Super Cars', 'A highly unsuccessful race car intended to be entered into the GT1 category of the BPR Global GT Series. It is notable as being the first Callaway car to not be based on a Corvette or existing designs.', 0),
  (1948, '1996', 'Callaway', 'C7', '', 'Hot Wheels', '2010 Hot Auction', '', 'Retro Super Cars', 'A highly unsuccessful race car intended to be entered into the GT1 category of the BPR Global GT Series. It is notable as being the first Callaway car to not be based on a Corvette or existing designs.', 0),
  (93, '1996', 'Callaway', 'C7', '', 'Hot Wheels', '', '', 'Retro Super Cars', 'A highly unsuccessful race car intended to be entered into the GT1 category of the BPR Global GT Series. It is notable as being the first Callaway car to not be based on a Corvette or existing designs.', 0),
  (2323, '', 'Carmichael', 'Commando', '', 'Matchbox', '1982 Mainline', '', '', 'The Carmichael Commando, in real life, was a fairly unique vehicle.  It was a three-axle 6x4 modified Land Rover Range Rover, which was offered as both a fire engine and a luxury SUV.  Many of the fire engine conversions are still in use in the UK, though all have been converted to 6x6, as there is a rule in the UK stating that all fire engines must be all-wheel drive.', 0),
  (2099, '', 'Case', 'Pulling Tractor (Race)', '', 'ERTL', '1/64 Pulling Tractors', '', 'Other', '', 0),
  (94, '', 'Caterham', 'Superlight RS500', '', 'Matchbox', '', '', 'Track Toys', 'The Caterham Seven Superlight R500 shows that when it comes to serving up an undiluted adrenaline hit, nobody does it better. Further weight has been taken out of the chassis and performance is suitably shattering.', 0),
  (1739, '', 'Caterham', 'Superlight RS500', '', 'Matchbox', '', '', '', '', 0),
  (95, '1967', 'Chaparral', '2D', '', 'Hot Wheels', '', '', 'Classic Racers', 'The car left a major mark in the World Endurance Championships, against famous competitors such as Ferrari and Porsche.', 0),
