  (3606, '2022', 'GMC', 'HUMMER EV', '', 'Majorette', '', '', 'Extreme Offroad', '', 0),
  (1672, '2024', 'GMC', 'HUMMER EV', 'Ken''s', 'Hot Wheels', '', '', '', '', 0),
  (3657, '1995', 'GMC', 'Jimmy', '', 'Majorette', 'Pinder', '', '', '', 0),
  (1571, '1997', 'GMC', 'School Bus', '', 'Matchbox', '', '', 'Vans & Utility', 'For 1997, GM introduced a cutaway-chassis version of the 3500-series Express/Savana. Intended for a wide variety of potential applications, cutaway chassis are best known as the basis of ambulances, buses, and recreational vehicles.', 0),
  (358, '1957', 'GMC', 'Stepside', '', 'Matchbox', '2013 Battle/Mission Combat 5-Pack', '', 'Vans & Utility', '', 0),
  (357, '1957', 'GMC', 'Stepside', '', 'Matchbox', '', '', 'Retro Muscle', '', 0),
  (2314, '2001', 'GMC', 'Terracross', '', 'Racing Champions', 'Concept and Muscle', '', 'Offroad Concepts', '', 0),
  (3734, '2010', 'GMC', 'Terradyne', '', 'Matchbox', '', '', '', '', 0),
  (3910, '2001', 'GMC', 'Yukon Denali', '', 'Welly', '', '', '', '', 0),
  (2410, '2024', 'Gordon Murray Automotive', 'T.33', '', 'Hot Wheels', '2024 HW Exotics', '', 'Hypercars', '', 0),
  (2411, '2020', 'Gordon Murray Automotive', 'T.50s', '', 'Hot Wheels', '2025 Factory Fresh', '', 'Extreme Track Toys', 'The T.50s is the track version of the iconic Gordon Murray Automotive T.50 supercar. It delivers an exhilarating on-track experience, representing the thrill of driving in its purest form.', 0),
  (176, '1973', 'GReddy', 'Fugu Z (Custom 240Z)', 'Datsun', 'Hot Wheels', '', 'Japan', 'Tuners & Imports', 'A naturally aspirated inline 6 motor with ITBs, wide body kit, deep bucket seats and a full roll cage make this custom Datsun 240Z the ultimate canyon carver! Check out the fender-mounted rear-view mirrors and watch the competition fade into the distance as you step on the gas.', 0),
  (1990, '1973', 'GReddy', 'Fugu Z (Custom 240Z)', 'Datsun', 'Hot Wheels', '2023 Japanese Car Culture Themed Multipack', 'USA', 'Tuners & Imports', 'The Fugu Z was dreamt up by Fast and Furious actor Sung Kang. It''s based on a 1973-model Datsun 240Z. The body kit is from wildly popular custom manufacturer Rocket Bunny. Even the engine is a piece of very particular engineering. It''s the renowned RB26DETT from the Skyline GT-R, but adapted to be naturally aspirated. No surprise this little gem won Gran Turismo''s Best in Show award at the 2015 SEMA event.', 0),
  (3693, '1973', 'GReddy', 'Fugu Z (Custom 240Z)', 'Sung Kang''s', 'Hot Wheels', '', 'USA', 'Tuners & Imports', 'The Fugu Z was dreamt up by Fast and Furious actor Sung Kang. It''s based on a 1973-model Datsun 240Z. The body kit is from wildly popular custom manufacturer Rocket Bunny. Even the engine is a piece of very particular engineering. It''s the renowned RB26DETT from the Skyline GT-R, but adapted to be naturally aspirated. No surprise this little gem won Gran Turismo''s Best in Show award at the 2015 SEMA event.', 0),
