  (1591, 'N/A', 'Hot Wheels', 'Jaded', '', 'Hot Wheels', '', 'El Segundo', 'Hot Wheels Special', 'Equipped with a parachute, wheelie bars, and a large wing, this powerful hot rod was designed to stay under control even at extreme velocities. Take a good look or all you�ll see is it�s giant rear spoiler flying past you.', 0),
  (972, 'N/A', 'Hot Wheels', 'Jet Threat 3.0', '', 'Hot Wheels', '2008 Team: Jet Rides', 'El Segundo', 'Hot Wheels Special', '', 0),
  (1600, 'N/A', 'Hot Wheels', 'Jet Threat 3.0', '', 'Hot Wheels', '', 'El Segundo', 'Hot Wheels Special', 'With two jet engines blasting from behind, this sleek racer extends its massive wings to fly by at unimaginable speeds.', 0),
  (2696, 'N/A', 'Hot Wheels', 'Kowloon''d Hypervan', '', 'Hot Wheels', '2024 HW Metro', '', 'Hot Wheels Special', '', 0),
  (417, 'N/A', 'Hot Wheels', 'Krazy 8''s', '', 'Hot Wheels', '2006 Track Aces', 'El Segundo', 'Hot Wheels Special', 'Krazy 8s is a depiction of a highly futuristic race car. Its name comes from the pair of inline-8 engines flanking both sides of the car, accompanied by the associated exhaust routing and other functional parts. The engines are said to be synchronized with each other and produce 850 horsepower.', 0),
